#include "crypto/passphrase_generator.h"

#include "crypto/crypto.h"
#include "eff_wordlist.h" // generated by core/CMakeLists.txt

#include <sodium.h>

#include <cctype>
#include <cmath>
#include <stdexcept>

namespace pb {

static_assert(sizeof(EFF_LONG_WORDLIST) / sizeof(EFF_LONG_WORDLIST[0]) == 7776,
              "the EFF long wordlist has 7776 words");

std::size_t passphrase_wordlist_size() {
    return sizeof(EFF_LONG_WORDLIST) / sizeof(EFF_LONG_WORDLIST[0]);
}

std::string_view passphrase_word(std::size_t index) {
    if (index >= passphrase_wordlist_size()) throw std::out_of_range("word index");
    return EFF_LONG_WORDLIST[index];
}

namespace {

void check(const passphrase_options& o) {
    if (o.words < passphrase_options::MIN_WORDS || o.words > passphrase_options::MAX_WORDS) {
        throw std::invalid_argument("word count out of range");
    }
    if (o.separator.size() > 3) throw std::invalid_argument("separator too long");
    for (const char c : o.separator) {
        if (std::isalpha(static_cast<unsigned char>(c)) || static_cast<unsigned char>(c) >= 0x80) {
            throw std::invalid_argument("separator must not contain letters");
        }
    }
}

std::uint32_t uniform(std::size_t n) { return randombytes_uniform(static_cast<std::uint32_t>(n)); }

} // namespace

secure_string generate_passphrase(const passphrase_options& o) {
    crypto::ensure_initialized();
    check(o);
    const std::size_t numbered = o.include_number ? uniform(o.words) : o.words;
    secure_string out;
    for (std::size_t i = 0; i < o.words; ++i) {
        if (i > 0) out += to_secure(o.separator);
        const std::string_view word = passphrase_word(uniform(passphrase_wordlist_size()));
        const std::size_t start = out.size();
        out.append(word.data(), word.size());
        if (o.capitalize) out[start] = static_cast<char>(std::toupper(static_cast<unsigned char>(out[start])));
        if (i == numbered) out += static_cast<char>('0' + uniform(10));
    }
    return out;
}

double passphrase_entropy_bits(const passphrase_options& o) {
    check(o);
    double bits = static_cast<double>(o.words) * std::log2(static_cast<double>(passphrase_wordlist_size()));
    if (o.include_number) bits += std::log2(10.0) + std::log2(static_cast<double>(o.words));
    return bits;
}

} // namespace pb
